  "assistant.thinking",
  "tool.call",
  "tool.result",
  "subagent.start",
  "subagent.stop",
  "compaction",
  "cost",
  "title",
  "system",
  "meta",
]);
export type EventKind = z.infer<typeof EventKind>;

